INSERT INTO `WORKFLOW_MASTER` (`Id`, `Collection_Code`, `Name`, `FDE_JSON_Rule`, `IDE_JSON_Rule`, `created_at`, `updated_at`, `CDE_JSON_Rule`, `IQV_JSON_Rule`, `DQV_JSON_Rule`, `CL_JSON_Rule`, `ImageArchive_JSON_Rule`, `CDE_Endpoint_Resolution_Rule`) VALUES
(1, 'INCFF', 'Forward Presentment - FED', '{"workflow": {"name": "x9-file-enrichment-fde-fed", "scope": "perCashLetter", "steps": [{"id": "lookup_collection_type", "sql": "SELECT Collection_Type FROM COLLECTION_TYPE_MASTER WHERE X9_Coll_Type_Ind = :collTypeInd AND File_Dest_RT = :destRT", "type": "sql_lookup", "table": "COLLECTION_TYPE_MASTER", "params": {"destRT": "$ctx.fileHeader.immediateDestination", "collTypeInd": "$ctx.currentCL.cashLetterHeader.collectionTypeIndicator"}, "on_error": {"goto": "end_with_error_collection_type"}, "on_success": {"save_as": "$ctx.currentCL.enrichmentData.collectionType"}, "description": "Identify collection type based on CollectionTypeInd and destination RT", "on_zero_match": {"goto": "end_with_error_collection_type"}}, {"id": "lookup_collection_code_primary", "sql": "SELECT Collection_Code FROM COLLECTION_CODE_ORIGRT_REF WHERE Coll_Type = :collType AND OriginRT = :originRT", "type": "sql_lookup", "table": "COLLECTION_CODE_ORIGRT_REF", "params": {"collType": "$ctx.currentCL.enrichmentData.collectionType", "originRT": "$ctx.fileHeader.immediateOrigin"}, "on_error": {"goto": "end_with_error_collection_code"}, "on_success": {"save_as": "$ctx.currentCL.enrichmentData.collectionCode"}, "description": "Identify collection code using primary table COLLECTION_CODE_ORIGRT_REF", "on_zero_match": {"goto": "lookup_collection_code_fallback"}}, {"id": "lookup_collection_code_fallback", "sql": "SELECT Coll_Code FROM COLLECTION_CODE_UD_REF WHERE Coll_Type = :collType AND OriginRT = :originRT AND UserField = :userField AND FedWorkType = :fedWorkType", "type": "sql_lookup", "table": "COLLECTION_CODE_UD_REF", "params": {"collType": "$ctx.currentCL.enrichmentData.collectionType", "originRT": "$ctx.fileHeader.immediateOrigin", "userField": "$ctx.currentCL.cashLetterHeader.userField", "fedWorkType": "$ctx.currentCL.cashLetterHeader.fedWorkType"}, "on_error": {"goto": "end_with_error_collection_code"}, "on_success": {"save_as": "$ctx.currentCL.enrichmentData.collectionCode"}, "description": "Fallback lookup for collection code using COLLECTION_CODE_UD_REF", "on_zero_match": {"goto": "end_with_error_collection_code"}}, {"id": "lookup_micr_range", "sql": "SELECT CONCAT(Bin_Start, \'-\', Bin_End) AS BinRange, CONCAT(BatchStart, \'-\', BatchEnd) AS BatchRange, FileDeadline FROM COLLECTION_CODE_MICR WHERE Coll_Type = :collType AND Coll_Code = :collCode", "type": "sql_lookup", "table": "COLLECTION_CODE_MICR", "params": {"collCode": "$ctx.currentCL.enrichmentData.collectionCode", "collType": "$ctx.currentCL.enrichmentData.collectionType"}, "on_error": {"goto": "end_with_error_micr_range"}, "on_success": {"save_as": {"$ctx.currentCL.enrichmentData.fileDeadline": "$row.FileDeadline", "$ctx.currentCL.enrichmentData.assignedBinNumberRange": "$row.BinRange", "$ctx.currentCL.enrichmentData.assignedBatchNumberRange": "$row.BatchRange"}}, "description": "Identify Bin/Batch number range and file deadline using COLLECTION_CODE_MICR", "on_zero_match": {"goto": "end_with_error_micr_range"}}, {"id": "derive_business_day", "type": "transform", "logic": {"true": "$ctx.fileHeader.fileCreationDate", "false": "$nextDate($ctx.fileHeader.fileCreationDate)", "condition": "$ctx.fileHeader.fileCreationTime <= $ctx.currentCL.enrichmentData.fileDeadline"}, "on_success": {"save_as": "$ctx.currentCL.enrichmentData.businessDay"}, "description": "Determine business day based on fileCreationTime and FileDeadline"}, {"id": "end_with_error_collection_type", "type": "return", "return": {"error": "COLLECTION_TYPE_NOT_FOUND", "details": "No record in COLLECTION_TYPE_MASTER"}}, {"id": "end_with_error_collection_code", "type": "return", "return": {"error": "COLLECTION_CODE_NOT_FOUND", "details": "No matching record in COLLECTION_CODE_ORIGRT_REF or COLLECTION_CODE_UD_REF"}}, {"id": "end_with_error_micr_range", "type": "return", "return": {"error": "MICR_RANGE_NOT_FOUND", "details": "No matching record in COLLECTION_CODE_MICR"}}], "settings": {"timeout_ms": 1000, "stop_on_error": false}, "description": "Enrich each cash letter in an X9 file with collection type, collection code, bin/batch ranges, and business day for FED forward presentment"}}', NULL, '2025-11-23 09:37:17', '2026-04-23 02:39:58', '{"workflow": {"name": "x9-item-enrichment-inclearing-v1", "scope": "perItem", "steps": [{"id": "init_item_context", "type": "transform", "on_success": {"save_as": {"$ctx.currentItem.exceptionCode": null, "$ctx.currentItem.enrichmentStatus": "IN_PROGRESS", "$ctx.currentItem.exceptionDetails": null}}, "description": "Initialize item enrichment output fields"}, {"id": "lookup_bank_master_rt", "sql": "SELECT OnUsFlag, Name, Description FROM BANK_MASTER_RT WHERE RT = :rt AND InclearingFlag = \'Y\' AND Status = \'ACTIVE\'", "type": "sql_lookup", "table": "BANK_MASTER_RT", "params": {"rt": "$ctx.currentItem.RT"}, "on_error": {"goto": "end_with_not_our_item"}, "on_success": {"save_as": {"$ctx.currentItem.bankName": "$row.Name", "$ctx.currentItem.onUsFlag": "$row.OnUsFlag", "$ctx.currentItem.bankDescription": "$row.Description", "$ctx.currentItem.Enriched_Data_01": "$row.OnUsFlag", "$ctx.currentItem.Enriched_Data_02": "$row.Name", "$ctx.currentItem.Enriched_Data_03": "$row.Description"}}, "description": "Validate item RT belongs to inclearing set; capture OnUsFlag", "on_zero_match": {"goto": "end_with_not_our_item"}}, {"id": "lookup_account_master", "sql": "SELECT AccountClass, ProductType, BranchCode, Currency, Status, CustomerID, CustomerName, PositivePayFlag, Check_Deposit_Limit FROM ALL_ACCOUNT_MASTER WHERE RT = :rt AND AccountNumber = :acct", "type": "sql_lookup", "table": "ALL_ACCOUNT_MASTER", "params": {"rt": "$ctx.currentItem.RT", "acct": "$ctx.currentItem.AccountNumber"}, "on_error": {"goto": "end_with_account_not_found"}, "on_success": {"save_as": "$ctx.vars.account"}, "description": "Load account master by RT + AccountNumber and validate account status and deposit limit", "on_zero_match": {"goto": "end_with_account_not_found"}}, {"id": "account_status_gate", "then": {"goto": "end_with_account_closed"}, "type": "condition", "when": "$ctx.vars.account.Status == \'CLOSED\'", "description": "Stop enrichment if account is CLOSED"}, {"id": "account_frozen_gate", "then": {"goto": "end_with_account_frozen"}, "type": "condition", "when": "$ctx.vars.account.Status == \'FROZEN\'", "description": "Stop enrichment if account is FROZEN"}, {"id": "deposit_limit_gate", "then": {"goto": "end_with_exceed_item_limit"}, "type": "condition", "when": "$ctx.currentItem.Amount > $ctx.vars.account.Check_Deposit_Limit", "description": "Stop enrichment if item amount exceeds deposit limit"}, {"id": "save_account_fields", "type": "transform", "on_success": {"save_as": {"$ctx.currentItem.Currency": "$ctx.vars.account.Currency", "$ctx.currentItem.BranchCode": "$ctx.vars.account.BranchCode", "$ctx.currentItem.CustomerID": "$ctx.vars.account.CustomerID", "$ctx.currentItem.ProductType": "$ctx.vars.account.ProductType", "$ctx.currentItem.AccountClass": "$ctx.vars.account.AccountClass", "$ctx.currentItem.CustomerName": "$ctx.vars.account.CustomerName", "$ctx.currentItem.AccountStatus": "$ctx.vars.account.Status", "$ctx.currentItem.PositivePayFlag": "$ctx.vars.account.PositivePayFlag", "$ctx.currentItem.Enriched_Data_04": "$ctx.vars.account.AccountClass", "$ctx.currentItem.Enriched_Data_05": "$ctx.vars.account.ProductType", "$ctx.currentItem.Enriched_Data_06": "$ctx.vars.account.BranchCode", "$ctx.currentItem.Enriched_Data_07": "$ctx.vars.account.Currency", "$ctx.currentItem.Enriched_Data_08": "$ctx.vars.account.Status", "$ctx.currentItem.Enriched_Data_09": "$ctx.vars.account.CustomerID", "$ctx.currentItem.Enriched_Data_10": "$ctx.vars.account.CustomerName", "$ctx.currentItem.Enriched_Data_11": "$ctx.vars.account.PositivePayFlag", "$ctx.currentItem.Enriched_Data_12": "$ctx.vars.account.Check_Deposit_Limit", "$ctx.currentItem.Check_Deposit_Limit": "$ctx.vars.account.Check_Deposit_Limit"}}, "description": "Copy account master fields into item payload"}, {"id": "pospay_skip_gate", "then": {"goto": "lookup_stop_pay"}, "type": "condition", "when": "$ctx.currentItem.PositivePayFlag != \'Y\'", "description": "If PositivePayFlag != Y skip to Stop Pay step"}, {"id": "lookup_positive_pay", "sql": "SELECT Pay_Status, IssueDate FROM POSITIVE_PAY_REF WHERE RT = :rt AND AccountNumber = :acct AND CheckSerialNumber = :serial AND Amount = :amt", "type": "sql_lookup", "table": "POSITIVE_PAY_REF", "params": {"rt": "$ctx.currentItem.RT", "amt": "$ctx.currentItem.Amount", "acct": "$ctx.currentItem.AccountNumber", "serial": "$ctx.currentItem.CheckSerialNumber"}, "on_error": {"goto": "end_with_positive_pay_return"}, "on_success": {"save_as": {"$ctx.currentItem.Enriched_Data_13": "$row.IssueDate", "$ctx.currentItem.Enriched_Data_14": "$row.Pay_Status", "$ctx.currentItem.PositivePay_IssueDate": "$row.IssueDate", "$ctx.currentItem.PositivePay_PayStatus": "$row.Pay_Status"}}, "description": "Validate issued check exists for RT+Account+Serial+Amount", "on_zero_match": {"goto": "end_with_positive_pay_return"}}, {"id": "lookup_stop_pay", "sql": "SELECT StopReasonCode, StopDate, Active FROM STOP_PAY_REF WHERE RT = :rt AND AccountNumber = :acct AND CheckSerialNumber = :serial AND Active = \'Y\'", "type": "sql_lookup", "table": "STOP_PAY_REF", "params": {"rt": "$ctx.currentItem.RT", "acct": "$ctx.currentItem.AccountNumber", "serial": "$ctx.currentItem.CheckSerialNumber"}, "on_error": {"goto": "lookup_fraud_watch"}, "on_success": {"save_as": {"$ctx.currentItem.StopPay_Active": "$row.Active", "$ctx.currentItem.Enriched_Data_15": "$row.StopReasonCode", "$ctx.currentItem.Enriched_Data_16": "$row.StopDate", "$ctx.currentItem.StopPay_StopDate": "$row.StopDate", "$ctx.currentItem.StopPay_StopReasonCode": "$row.StopReasonCode"}}, "description": "If stop pay exists for RT+Account+Serial => STOP_PAY_RETURN", "on_zero_match": {"goto": "lookup_fraud_watch"}}, {"id": "stop_pay_gate", "then": {"goto": "end_with_stop_pay_return"}, "type": "condition", "when": "$ctx.currentItem.StopPay_Active == \'Y\'", "description": "If stop pay matched, stop enrichment"}, {"id": "lookup_fraud_watch", "sql": "SELECT FraudFlagType, FraudReasonCode FROM FRAUD_WATCH_REF WHERE AccountNumber = :acct AND SerialNumber = :serial", "type": "sql_lookup", "table": "FRAUD_WATCH_REF", "params": {"acct": "$ctx.currentItem.AccountNumber", "serial": "$ctx.currentItem.CheckSerialNumber"}, "on_error": {"goto": "lookup_posting_code"}, "on_success": {"save_as": {"$ctx.currentItem.FraudFlagType": "$row.FraudFlagType", "$ctx.currentItem.FraudReasonCode": "$row.FraudReasonCode", "$ctx.currentItem.Enriched_Data_17": "$row.FraudFlagType", "$ctx.currentItem.Enriched_Data_18": "$row.FraudReasonCode"}}, "description": "If fraud watch matched for Account+Serial => COUNTERFEIT_SUSPECTED", "on_zero_match": {"goto": "lookup_posting_code"}}, {"id": "fraud_gate", "then": {"goto": "end_with_counterfeit_suspected"}, "type": "condition", "when": "$ctx.currentItem.FraudFlagType != null", "description": "If fraud matched stop enrichment"}, {"id": "lookup_posting_code", "sql": "SELECT TranCode, DebitCreditInd, GLAccount, Description FROM POSTING_CODE_REF WHERE RT = :rt AND AccountClass = :acctClass AND Active = \'Y\'", "type": "sql_lookup", "table": "POSTING_CODE_REF", "params": {"rt": "$ctx.currentItem.RT", "acctClass": "$ctx.vars.account.AccountClass"}, "on_error": {"goto": "end_with_posting_code_error"}, "on_success": {"save_as": {"$ctx.currentItem.Enriched_Data_19": "$row.TranCode", "$ctx.currentItem.Enriched_Data_20": "$row.DebitCreditInd", "$ctx.currentItem.Enriched_Data_21": "$row.GLAccount", "$ctx.currentItem.Enriched_Data_22": "$row.Description", "$ctx.currentItem.Posting_TranCode": "$row.TranCode", "$ctx.currentItem.Posting_GLAccount": "$row.GLAccount", "$ctx.currentItem.Posting_Description": "$row.Description", "$ctx.currentItem.Posting_DebitCreditInd": "$row.DebitCreditInd"}}, "description": "Find posting mapping for RT + AccountClass + TranCode", "on_zero_match": {"goto": "end_with_posting_code_error"}}, {"id": "lookup_endpoint_route", "sql": "SELECT EndpointRT, EndpointNetwork FROM ENDPOINT_ROUTE_REF WHERE RT = :rt AND Status = \'ACTIVE\'", "type": "sql_lookup", "table": "ENDPOINT_ROUTE_REF", "params": {"rt": "$ctx.currentItem.RT"}, "on_error": {"goto": "end_with_endpoint_route_error"}, "on_success": {"goto": "end_success"}, "description": "Find endpoint route for item RT", "on_zero_match": {"goto": "end_with_endpoint_route_error"}}, {"id": "end_with_error_missing_mod_rule", "type": "return", "return": {"error": "BR_DATA_MOD_ROUTINE_MISSING", "details": "No active MOD_ROUTINE found"}}, {"id": "end_success", "type": "return", "return": {"exceptionCode": null, "enrichmentStatus": "SUCCESS", "exceptionDetails": null}}, {"id": "end_with_invalid_rt", "type": "return", "return": {"error": "INVALID_RT", "details": "RT Mod-10 check failed"}}, {"id": "end_with_not_our_item", "type": "return", "return": {"error": "NOT_OUR_ITEM", "details": "No match in BANK_MASTER_RT"}}, {"id": "end_with_account_not_found", "type": "return", "return": {"error": "ACCOUNT_NOT_FOUND", "details": "No match in ALL_ACCOUNT_MASTER"}}, {"id": "end_with_account_closed", "type": "return", "return": {"error": "ACCOUNT_CLOSED", "details": "Account status is CLOSED"}}, {"id": "end_with_account_frozen", "type": "return", "return": {"error": "ACCOUNT_FROZEN", "details": "Account status is FROZEN"}}, {"id": "end_with_exceed_item_limit", "type": "return", "return": {"error": "EXCEED_ITEM_LIMIT", "details": "Item amount exceeded Check_Deposit_Limit"}}, {"id": "end_with_positive_pay_return", "type": "return", "return": {"error": "POSITIVE_PAY_RETURN", "details": "No match in POSITIVE_PAY_REF"}}, {"id": "end_with_stop_pay_return", "type": "return", "return": {"error": "STOP_PAY_RETURN", "details": "Matched STOP_PAY_REF record found"}}, {"id": "end_with_counterfeit_suspected", "type": "return", "return": {"error": "COUNTERFEIT_SUSPECTED", "details": "Matched FRAUD_WATCH_REF record found"}}, {"id": "end_with_posting_code_error", "type": "return", "return": {"error": "BR_DATA_POSTING_CODE_ERROR", "details": "No match in POSTING_CODE_REF"}}, {"id": "end_with_endpoint_route_error", "type": "return", "return": {"error": "BR_DATA_ENDPOINT_ROUTE_ERROR", "details": "No match in ENDPOINT_ROUTE_REF"}}], "settings": {"timeout_ms": 1000, "stop_on_error": true}, "description": "Inclearing check item enrichment using 8 lookup tables with stop-on-exception behavior"}}', '{"collectionCodeMap": {"INCFF": {"iqa": true, "iua": false, "fraud": false, "iuaOcr": false, "tiffValidation": true}}}', '{"validationRules": [{"field": "ACCOUNT", "required": true, "ruleName": "account_missing_check", "errorCode": "DQV_ACC_001", "parameters": {"sources": ["ORIG_MICR_ACCOUNT", "OCR_MICR_ACCOUNT"], "checkBothSources": true}, "errorMessage": "Account number is missing in both ORIG and OCR", "validationType": "ACCOUNT_VALIDATION"}, {"field": "ACCOUNT", "ruleName": "account_format_validation", "errorCode": "DQV_ACC_002", "parameters": {"maxLength": 17, "minLength": 4, "description": "Reject accounts with MICR special characters indicating OCR uncertainty", "specialChars": ["*", "-", "?", "#", "@", "!", "&", "%"], "rejectAllZeros": true, "allowOnlyDigits": true, "rejectRepeatedDigits": true, "rejectSpecialMicrChars": true}, "errorMessage": "Invalid account format", "validationType": "ACCOUNT_VALIDATION"}, {"field": "ACCOUNT", "ruleName": "account_conflict_check", "errorCode": "DQV_ACC_004", "parameters": {"compareFields": ["ORIG_MICR_ACCOUNT", "OCR_MICR_ACCOUNT"], "conflictAction": "DATA_CORRECTION"}, "errorMessage": "Account number conflict between ORIG and OCR", "validationType": "ACCOUNT_VALIDATION"}, {"field": "AMOUNT", "required": true, "ruleName": "amount_missing_check", "errorCode": "DQV_AMT_001", "parameters": {"sources": ["AMOUNT", "ORIG_MICR_AMOUNT", "OCR_MICR_AMOUNT"], "checkAllSources": true}, "errorMessage": "Amount is missing in all sources", "validationType": "AMOUNT_VALIDATION"}, {"field": "AMOUNT", "maxValue": 1000000.0, "minValue": 0.01, "ruleName": "amount_range_validation", "errorCode": "DQV_AMT_002", "parameters": {"rejectZero": true, "rejectNegative": true}, "errorMessage": "Amount must be positive and within limits", "validationType": "AMOUNT_VALIDATION"}, {"field": "AMOUNT", "ruleName": "amount_conflict_check", "errorCode": "DQV_AMT_005", "tolerance": 1.0, "parameters": {"compareFields": ["AMOUNT", "ORIG_MICR_AMOUNT", "OCR_MICR_AMOUNT"], "conflictAction": "DATA_CORRECTION", "toleranceAmount": 1.0}, "compareField": "OCR_MICR_AMOUNT", "errorMessage": "Amount conflict between sources", "validationType": "AMOUNT_VALIDATION"}, {"field": "RT", "required": true, "ruleName": "rt_missing_check", "errorCode": "DQV_RT_001", "parameters": {"sources": ["ORIG_MICR_RT", "OCR_MICR_RT"], "checkBothSources": true}, "errorMessage": "Routing Transit number is missing", "validationType": "RT_VALIDATION"}, {"field": "RT", "pattern": "^\\\\d{9}$", "ruleName": "rt_format_and_mod10_validation", "errorCode": "DQV_RT_002", "parameters": {"length": 9, "description": "RT must be exactly 9 digits, pass mod-10 checksum validation, and not contain MICR special characters", "mod10Weights": [3, 7, 1, 3, 7, 1, 3, 7, 1], "specialChars": ["*", "-", "?", "#", "@", "!", "&", "%"], "mod10Algorithm": "ABA_ROUTING_NUMBER", "allowOnlyDigits": true, "performMod10Check": true, "rejectSpecialMicrChars": true}, "errorMessage": "Invalid RT format or mod-10 check failed", "validationType": "RT_VALIDATION"}, {"field": "RT", "ruleName": "rt_conflict_check", "errorCode": "DQV_RT_004", "parameters": {"compareFields": ["ORIG_MICR_RT", "OCR_MICR_RT"], "conflictAction": "DATA_CORRECTION"}, "errorMessage": "RT conflict between ORIG and OCR", "validationType": "RT_VALIDATION"}, {"field": "CHECK_NUMBER", "ruleName": "check_number_validation", "errorCode": "DQV_CHK_001", "parameters": {"maxLength": 10, "allowOnlyNumeric": true, "requiredIfPresent": false}, "errorMessage": "Invalid check number format", "validationType": "CHECK_NUMBER_VALIDATION"}, {"field": "ALL_MICR_FIELDS", "ruleName": "MICR_SPECIAL_CHAR_CHECK", "errorCode": "DQV_MICR_001", "parameters": {"fields": ["ORIG_MICR_ONUS", "ORIG_MICR_EPC", "ORIG_MICR_AUXONUS", "OCR_MICR_PC", "OCR_MICR_EPC", "OCR_MICR_AUXONUS", "OCR_MICR_FIELD4"], "description": "Check all MICR fields for special characters (*, -, ?, etc.) that indicate OCR read uncertainty or errors", "specialChars": ["*", "-", "?", "#", "@", "!", "&", "%"]}, "errorMessage": "MICR field contains special characters indicating OCR uncertainty", "validationType": "CUSTOM"}]}', '{"maxAmount": 10000000.0, "maxItemCount": 5000, "timeCutoffMinutes": 480, "idleTimeoutMinutes": 30}', '{"cofConfig": {"includeHeader": true, "fieldDelimiter": "\\t"}, "ciffConfig": {"originatorId": "CCP_ARCHIVE", "formatVersion": "CIFF-1.0"}, "outputFormats": ["CIFF", "COF"], "metadataFields": ["RT", "ACCOUNT_NUMBER", "AMOUNT", "ON_US", "AUX_ON_US", "EPC", "ENRICHED_DATA_01", "ENRICHED_DATA_02", "ENRICHED_DATA_03", "ENRICHED_DATA_04", "ENRICHED_DATA_05", "PROCESSING_STATUS", "EXCEPTION_CODE", "COLLECTION_CODE", "BUSINESS_DATE", "FILE_ID", "CASHLETTER_ID", "BUNDLE_ID", "PAYMENT_ID"]}', '{"steps": [{"id": "lookup_endpoint", "sql": "SELECT ENDPOINT_RT, ENDPOINT_NETWORK FROM ENDPOINT_RESOLUTION_RULES WHERE COLLECTION_CODE = :cc AND DIRECTION = :dir AND (RT_PATTERN IS NULL OR RT_PATTERN = :rt) AND ACTIVE = 1 ORDER BY PRIORITY ASC LIMIT 1", "type": "sql_lookup", "table": "ENDPOINT_RESOLUTION_RULES", "params": {"cc": "\\\\.currentItem.CollectionCode", "rt": "\\\\.currentItem.RT", "dir": "\\\\.currentItem.Direction"}, "onNoMatch": {"set": {"flagForReview": true}}, "outputMapping": {"endpointRt": "ENDPOINT_RT", "endpointNetwork": "ENDPOINT_NETWORK"}}]}'),
(2, 'INCFB', 'Forward Presentment - Bank of America', '{"workflow": {"name": "x9-file-enrichment-fde-bofa", "scope": "perCashLetter", "steps": [{"id": "lookup_collection_type", "sql": "SELECT Collection_Type FROM COLLECTION_TYPE_MASTER WHERE X9_Coll_Type_Ind = :collTypeInd AND File_Dest_RT = :destRT", "type": "sql_lookup", "table": "COLLECTION_TYPE_MASTER", "params": {"destRT": "$ctx.fileHeader.immediateDestination", "collTypeInd": "$ctx.currentCL.cashLetterHeader.collectionTypeIndicator"}, "on_error": {"goto": "end_with_error_collection_type"}, "on_success": {"save_as": "$ctx.currentCL.enrichmentData.collectionType"}, "description": "Identify collection type based on CollectionTypeInd and destination RT", "on_zero_match": {"goto": "end_with_error_collection_type"}}, {"id": "lookup_collection_code_primary", "sql": "SELECT Collection_Code FROM COLLECTION_CODE_ORIGRT_REF WHERE Coll_Type = :collType AND OriginRT = :originRT", "type": "sql_lookup", "table": "COLLECTION_CODE_ORIGRT_REF", "params": {"collType": "$ctx.currentCL.enrichmentData.collectionType", "originRT": "$ctx.fileHeader.immediateOrigin"}, "on_error": {"goto": "end_with_error_collection_code"}, "on_success": {"save_as": "$ctx.currentCL.enrichmentData.collectionCode"}, "description": "Identify collection code using primary table COLLECTION_CODE_ORIGRT_REF", "on_zero_match": {"goto": "lookup_collection_code_fallback"}}, {"id": "lookup_collection_code_fallback", "sql": "SELECT Coll_Code FROM COLLECTION_CODE_UD_REF WHERE Coll_Type = :collType AND OriginRT = :originRT AND UserField = :userField AND FedWorkType = :fedWorkType", "type": "sql_lookup", "table": "COLLECTION_CODE_UD_REF", "params": {"collType": "$ctx.currentCL.enrichmentData.collectionType", "originRT": "$ctx.fileHeader.immediateOrigin", "userField": "$ctx.currentCL.cashLetterHeader.userField", "fedWorkType": "$ctx.currentCL.cashLetterHeader.fedWorkType"}, "on_error": {"goto": "end_with_error_collection_code"}, "on_success": {"save_as": "$ctx.currentCL.enrichmentData.collectionCode"}, "description": "Fallback lookup for collection code using COLLECTION_CODE_UD_REF", "on_zero_match": {"goto": "end_with_error_collection_code"}}, {"id": "lookup_micr_range", "sql": "SELECT CONCAT(Bin_Start, \'-\', Bin_End) AS BinRange, CONCAT(BatchStart, \'-\', BatchEnd) AS BatchRange, FileDeadline FROM COLLECTION_CODE_MICR WHERE Coll_Type = :collType AND Coll_Code = :collCode", "type": "sql_lookup", "table": "COLLECTION_CODE_MICR", "params": {"collCode": "$ctx.currentCL.enrichmentData.collectionCode", "collType": "$ctx.currentCL.enrichmentData.collectionType"}, "on_error": {"goto": "end_with_error_micr_range"}, "on_success": {"save_as": {"$ctx.currentCL.enrichmentData.fileDeadline": "$row.FileDeadline", "$ctx.currentCL.enrichmentData.assignedBinNumberRange": "$row.BinRange", "$ctx.currentCL.enrichmentData.assignedBatchNumberRange": "$row.BatchRange"}}, "description": "Identify Bin/Batch number range and file deadline using COLLECTION_CODE_MICR", "on_zero_match": {"goto": "end_with_error_micr_range"}}, {"id": "derive_business_day", "type": "transform", "logic": {"true": "$ctx.fileHeader.fileCreationDate", "false": "$nextDate($ctx.fileHeader.fileCreationDate)", "condition": "$ctx.fileHeader.fileCreationTime <= $ctx.currentCL.enrichmentData.fileDeadline"}, "on_success": {"save_as": "$ctx.currentCL.enrichmentData.businessDay"}, "description": "Determine business day based on fileCreationTime and FileDeadline"}, {"id": "end_with_error_collection_type", "type": "return", "return": {"error": "COLLECTION_TYPE_NOT_FOUND", "details": "No record in COLLECTION_TYPE_MASTER"}}, {"id": "end_with_error_collection_code", "type": "return", "return": {"error": "COLLECTION_CODE_NOT_FOUND", "details": "No matching record in COLLECTION_CODE_ORIGRT_REF or COLLECTION_CODE_UD_REF"}}, {"id": "end_with_error_micr_range", "type": "return", "return": {"error": "MICR_RANGE_NOT_FOUND", "details": "No matching record in COLLECTION_CODE_MICR"}}], "settings": {"timeout_ms": 1000, "stop_on_error": false}, "description": "Enrich each cash letter in an X9 file with collection type, collection code, bin/batch ranges, and business day for Bank of America forward presentment"}}', NULL, '2025-11-23 09:38:44', '2026-04-23 02:39:58', '{"workflow": {"name": "x9-item-enrichment-inclearing-v1", "scope": "perItem", "steps": [{"id": "init_item_context", "type": "transform", "on_success": {"save_as": {"$ctx.currentItem.exceptionCode": null, "$ctx.currentItem.enrichmentStatus": "IN_PROGRESS", "$ctx.currentItem.exceptionDetails": null}}, "description": "Initialize item enrichment output fields"}, {"id": "lookup_bank_master_rt", "sql": "SELECT OnUsFlag, Name, Description FROM BANK_MASTER_RT WHERE RT = :rt AND InclearingFlag = \'Y\' AND Status = \'ACTIVE\'", "type": "sql_lookup", "table": "BANK_MASTER_RT", "params": {"rt": "$ctx.currentItem.RT"}, "on_error": {"goto": "end_with_not_our_item"}, "on_success": {"save_as": {"$ctx.currentItem.bankName": "$row.Name", "$ctx.currentItem.onUsFlag": "$row.OnUsFlag", "$ctx.currentItem.bankDescription": "$row.Description", "$ctx.currentItem.Enriched_Data_01": "$row.OnUsFlag", "$ctx.currentItem.Enriched_Data_02": "$row.Name", "$ctx.currentItem.Enriched_Data_03": "$row.Description"}}, "description": "Validate item RT belongs to inclearing set; capture OnUsFlag", "on_zero_match": {"goto": "end_with_not_our_item"}}, {"id": "lookup_account_master", "bank": "JPMC", "type": "api_lookup", "params": {"rt": "$ctx.currentItem.RT", "accountNumber": "$ctx.currentItem.AccountNumber"}, "apiAlias": "account_validation_api", "on_error": {"goto": "end_with_account_not_found"}, "on_success": {"save_as": "$ctx.vars.account"}, "description": "Load account master via bank API", "on_zero_match": {"goto": "end_with_account_not_found"}, "collectionCode": "INCFB"}, {"id": "account_status_gate", "then": {"goto": "end_with_account_closed"}, "type": "condition", "when": "$ctx.vars.account.Status == \'CLOSED\'", "description": "Stop enrichment if account is CLOSED"}, {"id": "account_frozen_gate", "then": {"goto": "end_with_account_frozen"}, "type": "condition", "when": "$ctx.vars.account.Status == \'FROZEN\'", "description": "Stop enrichment if account is FROZEN"}, {"id": "deposit_limit_gate", "then": {"goto": "end_with_exceed_item_limit"}, "type": "condition", "when": "$ctx.currentItem.Amount > $ctx.vars.account.Check_Deposit_Limit", "description": "Stop enrichment if item amount exceeds deposit limit"}, {"id": "save_account_fields", "type": "transform", "on_success": {"save_as": {"$ctx.currentItem.Currency": "$ctx.vars.account.Currency", "$ctx.currentItem.BranchCode": "$ctx.vars.account.BranchCode", "$ctx.currentItem.CustomerID": "$ctx.vars.account.CustomerID", "$ctx.currentItem.ProductType": "$ctx.vars.account.ProductType", "$ctx.currentItem.AccountClass": "$ctx.vars.account.AccountClass", "$ctx.currentItem.CustomerName": "$ctx.vars.account.CustomerName", "$ctx.currentItem.AccountStatus": "$ctx.vars.account.Status", "$ctx.currentItem.PositivePayFlag": "$ctx.vars.account.PositivePayFlag", "$ctx.currentItem.Enriched_Data_04": "$ctx.vars.account.AccountClass", "$ctx.currentItem.Enriched_Data_05": "$ctx.vars.account.ProductType", "$ctx.currentItem.Enriched_Data_06": "$ctx.vars.account.BranchCode", "$ctx.currentItem.Enriched_Data_07": "$ctx.vars.account.Currency", "$ctx.currentItem.Enriched_Data_08": "$ctx.vars.account.Status", "$ctx.currentItem.Enriched_Data_09": "$ctx.vars.account.CustomerID", "$ctx.currentItem.Enriched_Data_10": "$ctx.vars.account.CustomerName", "$ctx.currentItem.Enriched_Data_11": "$ctx.vars.account.PositivePayFlag", "$ctx.currentItem.Enriched_Data_12": "$ctx.vars.account.Check_Deposit_Limit", "$ctx.currentItem.Check_Deposit_Limit": "$ctx.vars.account.Check_Deposit_Limit"}}, "description": "Copy account master fields into item payload"}, {"id": "pospay_skip_gate", "then": {"goto": "lookup_stop_pay"}, "type": "condition", "when": "$ctx.currentItem.PositivePayFlag != \'Y\'", "description": "If PositivePayFlag != Y skip to Stop Pay step"}, {"id": "lookup_positive_pay", "sql": "SELECT Pay_Status, IssueDate FROM POSITIVE_PAY_REF WHERE RT = :rt AND AccountNumber = :acct AND CheckSerialNumber = :serial AND Amount = :amt", "type": "sql_lookup", "table": "POSITIVE_PAY_REF", "params": {"rt": "$ctx.currentItem.RT", "amt": "$ctx.currentItem.Amount", "acct": "$ctx.currentItem.AccountNumber", "serial": "$ctx.currentItem.CheckSerialNumber"}, "on_error": {"goto": "end_with_positive_pay_return"}, "on_success": {"save_as": {"$ctx.currentItem.Enriched_Data_13": "$row.IssueDate", "$ctx.currentItem.Enriched_Data_14": "$row.Pay_Status", "$ctx.currentItem.PositivePay_IssueDate": "$row.IssueDate", "$ctx.currentItem.PositivePay_PayStatus": "$row.Pay_Status"}}, "description": "Validate issued check exists for RT+Account+Serial+Amount", "on_zero_match": {"goto": "end_with_positive_pay_return"}}, {"id": "lookup_stop_pay", "sql": "SELECT StopReasonCode, StopDate, Active FROM STOP_PAY_REF WHERE RT = :rt AND AccountNumber = :acct AND CheckSerialNumber = :serial AND Active = \'Y\'", "type": "sql_lookup", "table": "STOP_PAY_REF", "params": {"rt": "$ctx.currentItem.RT", "acct": "$ctx.currentItem.AccountNumber", "serial": "$ctx.currentItem.CheckSerialNumber"}, "on_error": {"goto": "lookup_fraud_watch"}, "on_success": {"save_as": {"$ctx.currentItem.StopPay_Active": "$row.Active", "$ctx.currentItem.Enriched_Data_15": "$row.StopReasonCode", "$ctx.currentItem.Enriched_Data_16": "$row.StopDate", "$ctx.currentItem.StopPay_StopDate": "$row.StopDate", "$ctx.currentItem.StopPay_StopReasonCode": "$row.StopReasonCode"}}, "description": "If stop pay exists for RT+Account+Serial => STOP_PAY_RETURN", "on_zero_match": {"goto": "lookup_fraud_watch"}}, {"id": "stop_pay_gate", "then": {"goto": "end_with_stop_pay_return"}, "type": "condition", "when": "$ctx.currentItem.StopPay_Active == \'Y\'", "description": "If stop pay matched, stop enrichment"}, {"id": "lookup_fraud_watch", "sql": "SELECT FraudFlagType, FraudReasonCode FROM FRAUD_WATCH_REF WHERE AccountNumber = :acct AND SerialNumber = :serial", "type": "sql_lookup", "table": "FRAUD_WATCH_REF", "params": {"acct": "$ctx.currentItem.AccountNumber", "serial": "$ctx.currentItem.CheckSerialNumber"}, "on_error": {"goto": "lookup_posting_code"}, "on_success": {"save_as": {"$ctx.currentItem.FraudFlagType": "$row.FraudFlagType", "$ctx.currentItem.FraudReasonCode": "$row.FraudReasonCode", "$ctx.currentItem.Enriched_Data_17": "$row.FraudFlagType", "$ctx.currentItem.Enriched_Data_18": "$row.FraudReasonCode"}}, "description": "If fraud watch matched for Account+Serial => COUNTERFEIT_SUSPECTED", "on_zero_match": {"goto": "lookup_posting_code"}}, {"id": "fraud_gate", "then": {"goto": "end_with_counterfeit_suspected"}, "type": "condition", "when": "$ctx.currentItem.FraudFlagType != null", "description": "If fraud matched stop enrichment"}, {"id": "lookup_posting_code", "sql": "SELECT TranCode, DebitCreditInd, GLAccount, Description FROM POSTING_CODE_REF WHERE RT = :rt AND AccountClass = :acctClass AND TranCode = :tranCode AND Active = \'Y\'", "type": "sql_lookup", "table": "POSTING_CODE_REF", "params": {"rt": "$ctx.currentItem.RT", "tranCode": "$ctx.currentItem.TranCode", "acctClass": "$ctx.vars.account.AccountClass"}, "on_error": {"goto": "end_with_posting_code_error"}, "on_success": {"save_as": {"$ctx.currentItem.Enriched_Data_19": "$row.TranCode", "$ctx.currentItem.Enriched_Data_20": "$row.DebitCreditInd", "$ctx.currentItem.Enriched_Data_21": "$row.GLAccount", "$ctx.currentItem.Enriched_Data_22": "$row.Description", "$ctx.currentItem.Posting_TranCode": "$row.TranCode", "$ctx.currentItem.Posting_GLAccount": "$row.GLAccount", "$ctx.currentItem.Posting_Description": "$row.Description", "$ctx.currentItem.Posting_DebitCreditInd": "$row.DebitCreditInd"}}, "description": "Find posting mapping for RT + AccountClass + TranCode", "on_zero_match": {"goto": "end_with_posting_code_error"}}, {"id": "lookup_endpoint_route", "